#define pb push_back
#define vll vector<ll>
#define F first
#define S second
#define all(x) (x).begin(), (x).end()
vector<vector<ii> >adj;
int c[2];
int colour[700005];
bool ok;
int n;
void dfs(int idx){
    c[colour[idx]]+= (idx <= n);
    for(auto x:adj[idx]){
        if(colour[x.F] == -1){
            colour[x.F] = colour[idx] ^ x.S;
            dfs(x.F);
        }
        else if(colour[x.F] != (colour[idx] ^ x.S)){
            ///impossible
            ok = false;
        }
    }
