int main(void){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    int t;
    cin>>t;
    while(t--){
        int m;
        cin>>n>>m;
        ///n original + m atmost fake nodes
        adj.assign(n+m+5,vector<ii>());
        f(i,0,n+m+5){
            colour[i] = -1;
        }
        int fake = n+1;
        f(i,0,m){
            int a,b;
            string c;
            cin>>a>>b>>c;
            if(c == "crewmate"){
                ///same team
                adj[a].pb(ii(fake,1));
                adj[fake].pb(ii(a,1));
                adj[fake].pb(ii(b,1));
                adj[b].pb(ii(fake,1));
                fake++;
            }
            else{
                ///different team
                adj[a].pb(ii(b,1));
                adj[b].pb(ii(a,1));
            }
        }
        int ans = 0;
        ok = true;
        f(i,1,n+1){
            if(colour[i] == -1){
                colour[i] = 0;
                c[0] = c[1] = 0;
                dfs(i);
                ans += max(c[0],c[1]);
            }
        }
        if(!ok){
            ans = -1;
        }
        cout<<ans<<"\n";
    }
}

